// 《地道里的光》 —— 核心逻辑层（横版 2.5D，参考《勇敢的心：世界大战》）。
// 剧本来源：Notion《地道里的光》剧本大纲 + 关卡设计（八章结构）。
// 设计三原则：每关一个小人物目标；用行动而非台词表现成长；目标是保护群众、保存力量，而不是消灭敌人。
// 空间语法：x 为横向米数，level 为 surface（地表 y=0）/ under（地道 y=-3.6）。
// 地道场景是「剖面视角」：地表与地下同屏，烟、探杆、转移全部在一维横轴上展开。

// 场景布局是数据不是代码：坐标/尺寸/旗标门在 Data_Scenes.json，贴图与深度带在
// Data_PropArt.json，加载与校验在 Data_Scenes.mjs（配错在加载时就抛）。
import { SCENES } from "./Data_Scenes.mjs";
import { VaultLiftFor, VAULT_MAX_TOP } from "./Data_DepthSpec.mjs";
import { LADDER } from "./Data_Ladder.mjs";
// 剧本按章拆在 Data_ScriptC1..C8.mjs（2026-08-15）——组装在本文件末尾（SCRIPT_KIT）。
import { ChapterC1 } from "./Data_ScriptC1.mjs";
import { ChapterC2 } from "./Data_ScriptC2.mjs";
import { ChapterC3 } from "./Data_ScriptC3.mjs";
import { ChapterC4 } from "./Data_ScriptC4.mjs";
import { ChapterC5 } from "./Data_ScriptC5.mjs";
import { ChapterC6 } from "./Data_ScriptC6.mjs";
import { ChapterC7 } from "./Data_ScriptC7.mjs";
import { ChapterC8 } from "./Data_ScriptC8.mjs";

export const GAME_VERSION = "0.3.0";

export const SURFACE_Y = 0;
export const UNDER_Y = -3.6;

export { SCENES };

// ---------------------------------------------------------------------------
// 交互提示的写法（勇敢的心式）
// ---------------------------------------------------------------------------
// 提示 = 一枚按钮徽章 + 一个短动词。**文案里不写键名**——手机上没有键盘，
// 「按 E」三个字在那儿就是句废话；键位写成前缀 `E · ` / `按住 E · `，
// 由 HUD 按当前输入设备翻成键帽或触屏图标（见 Script_Main.PromptChip）。
// 动词要短：一眼扫过去就懂，别写成一句话——为什么、怎么做，交给画面和手记条。
// 长按的百分比也别写进文案，promptFill 会画成徽章外圈那道进度环。
const PROMPT_ACTS = { E: "interact", F: "throw", C: "crouch", W: "up", S: "down" };

// 把 `按住 E · 接绳` 拆成 { act:"interact", hold:true, text:"接绳" }。
// 认不出前缀的当成没有按键的状态行（"跟上娘""手里拿着桶"），HUD 走另一条样式。
// `dir`：四动词里那半个方向（「按住 E ＋ ↑ · 掀开翻板」）。键名不进正文——
// 前缀里认出来，HUD 翻成第二枚键帽（键盘是箭头键，触屏是摇杆方向）。
// 「↔」＝左右都行（掰红薯干、顺着坛肩来回抹）：HUD 画成一枚双向键帽
const PROMPT_DIRS = { "↑": "up", "↓": "down", "←": "left", "→": "right", "↔": "horiz" };
export function SplitPrompt(raw) {
  if (!raw) return null;
  const m = /^(按住\s*)?([EFCWS])(?:\s*[＋+]\s*([↑↓←→↔]))?\s*·\s*([\s\S]+)$/.exec(raw);
  if (!m) return { act: null, hold: false, dir: null, text: raw };
  return { act: PROMPT_ACTS[m[2]], hold: !!m[1], dir: PROMPT_DIRS[m[3]] || null, text: m[4] };
}

// ---------------------------------------------------------------------------
// 章节元数据
// ---------------------------------------------------------------------------
// 章名取各章自己最硬的那个意象，不用"失去/陷阱/反击"这类空话：
// 蓝底白花=娘那块布（坛口的碎布垫圈→窖角没下过剪子的整布→撕成绷条→
// 接在妹妹袖口上，一章的两头都过玩家的手）；地洞里的眼睛=黑洞口回望那一镜；
// 半袋烟的工夫=换岗的空当，学会看的那一课；最后一盏灯=熄灯后攥在手里的那盏；
// 东口的铃=改造的回报；没套的骡车=推理的破绽本身。
// （一二章 2026-08-11 按 Notion「剧本新生」重写；三章起仍是旧线，待逐章翻新）
// **章号（2026-08-17 用户重排分镜定的）**：序·那天与原第一章合并为「序章」，原
// 《第二章 · 梳篦》顺位为「第一章」；第三章及以后 Notion 上还挂着旧章号（尚未顺移，
// 翻新时一并处理），这儿也照旧。序末的章名卡与章末字样跟这张表同口径
//（Data_ScriptC1 的 titleCard：「序章 · 蓝底白花」「序章结束」）。
