// ---------------------------------------------------------------------------
// 小工具
// ---------------------------------------------------------------------------
function InZone(px, level, zone) {
  const zoneLevel = zone.level || "surface";
  return level === zoneLevel && Math.abs(px - zone.x) <= zone.w / 2;
}

function SceneOf(state) { return SCENES[CHAPTERS[state.chapterIndex].scene]; }

// ---------------------------------------------------------------------------
// 屋里 / 屋外（可进入的屋子只有柱子家一处，规则却是全作的）
//
// 2.5D 横版里，玩家走的那条线是**村街**，屋子立在街后面。走进屋子那一段路
// 就把立面淡出——这是勇敢的心的里外切换，走路时没毛病；可它只看 x，于是
// **推着独轮车也能"进屋"**：从西边推过来，等于推着一车木料穿过自家后墙，
// 从堂屋里碾过去（用户 2026-08-09：「我推车为什么能推到家里去？这明明应该
// 走外面的小路的」）。
//
// 规矩：**车进不了屋**。手边有车（推着走）或车就停在屋前那段街上时，人走的
// 是屋外那条道——立面合着，人和车从屋子前面过去。空着手才是进屋。
// 配套的深度在 Data_DepthSpec：推着的车走 pushCart 带（压在立面之前），
// 否则立面会把整辆车吃掉，"从屋前过"就成了"车凭空消失"。
// ---------------------------------------------------------------------------
export const CART_REACH = 2.6;   // 手边有车 = 推着它（翻越判定用的是同一个数）

// ---------------------------------------------------------------------------
// 镜头会不会自己动：**总开关，默认关**
// ---------------------------------------------------------------------------
// 2026-08-10 用户定：「目前我看不需要这个自动摇动镜头的功能，把这个开关/功能
// 默认关闭吧」。所以窖口探头（走到地窖口镜头自动下沉、把脚底下那间窖带进画框）
// 整个停用——镜头**只跟着人走**，不自己找东西看。
//
// 机制照旧留在代码里（Core 算 cellarPeek、Main 的 BaseShot 用它压低 y、
// state.steadyCam 那套让位判据都在），要回来只需把这一行改成 true。
// 代价说在前头：关掉之后，站在窖口按 S 之前是看不见那间窖的——
// 地表机位的下边沿只到 −1.7m，窖底在 −3.6m。真要让玩家"下去之前先看见"，
// 下次换别的路子（一拍固定机位的插入镜、或者过场里交代），别再默认开自动摇镜。
export const CAM_CELLAR_PEEK = false;

export function PushingCart(state) {
  return !!state.cart && Math.abs(state.player.x - state.cart.x) < CART_REACH;
}

// 屋子占的那一段街。判定与画面共用一份边界——分开写迟早对不上
// （西头留 0.4 是山墙的厚度，东头多给 0.2 是门洞外那半步）
export function HouseSpan(prop) {
  return { x0: prop.x - prop.w / 2 + 0.4, x1: prop.x + prop.w / 2 + 0.2 };
}

// 立面该不该淡出（渲染层与冒烟测试同一个判据）
export function IndoorOpen(state, x0, x1) {
  const p = state.player;
  if (p.level !== "surface" || !(p.x > x0 && p.x < x1)) return false;
  if (state.cart && (PushingCart(state) || (state.cart.x > x0 && state.cart.x < x1))) return false;
  return true;
}

// ---------------------------------------------------------------------------
// 剧本：八个章节的 beat 序列（叙事文本沿用三轮迭代验证过的版本）
// cam hint 语法（勇敢的心式）：只允许 横移/升降/推拉，镜头切换=硬切+慢推
//   {kind:"follow"} 跟随 | {kind:"wide", x} 全景 | {kind:"shot", x, y, dist, pan?} 固定构图
// ---------------------------------------------------------------------------
const V = SCENES.village.zones;
const F = SCENES.fields.zones;
const TV = SCENES.tunnelVillage.zones;
const TF = SCENES.tunnelFort.zones;

function FindActor(state, id) { return state.actors.find((a) => a.id === id); }

// 配音行 id：按"说话人 + 文本"取哈希。抽词脚本（Script_VoiceExtract）与
// 运行时查表都走这一个函数——两边各写一份迟早会对不上，音频就整批哑掉。
// 用文本而不是行序做键，改动剧本顺序不会让已烘的音频失效，重复的句子也
// 自然共用同一个文件。
// 地道净高：一段一段不一样。冀中地道干线净高多在 1.2–1.5 米，
// **猫腰是常态**；卡口、新掏的段更矮，得半蹲甚至爬过去；能直起腰的只有
// 藏人洞和洞室。四档姿态由这一个函数说了算——玩法（速度、姿势）、
// 美术（洞腔画多高）、光照（空气腔多高）都从这儿取，免得三边各说各的。
export const POSTURE_HEAD = { stand: 2.05, stoop: 1.45, squat: 1.05, crawl: 0.72 };
export const POSTURE_SPEED = { stand: 1.0, stoop: 0.72, squat: 0.5, crawl: 0.34 };

export function TunnelPosture(scene, x) {
  // 藏人洞与洞室：唯一直得起腰的地方
  for (const pr of scene.props) {
    if (pr.kind !== "chamber" && pr.kind !== "pocket") continue;
    if (Math.abs(x - pr.x) < (pr.w || 5.6) / 2 - 0.6) return "stand";
  }
  // 剧情指定的窄段（卡口 / 连夜掏出来的那几十步）：得爬
  for (const t of scene.tight || []) {
    if (x >= t.x0 && x <= t.x1) return t.mode || "crawl";
  }
  // 其余：猫腰打底，隔一段一处半蹲的矮腰。按位置取值，稳定可预期
  const n = Math.sin(x * 0.17) * 0.6 + Math.sin(x * 0.052 + 1.7) * 0.4;
  return n > 0.30 ? "squat" : "stoop";
}

export function VoiceLineId(who, text) {
  const src = (who || "") + "|" + text;
  let h = 2166136261;
  for (let i = 0; i < src.length; i += 1) {
    h ^= src.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h.toString(36).padStart(7, "0");
}

// 配音时长表：开了声音之后，一行字幕至少得停到旁白念完，否则每句都被
// 切在半截。剧本里手写的 d 仍然是下限——它定的是"这一拍该有多长"，
// 配音只负责把太短的那些撑开。静音时这张表是空的，节奏回到原样。
let VOICE_DUR = null;
export function SetVoiceDurations(map) { VOICE_DUR = map; }

// 旁白还在念的时候不许切下一行。
//
// 原先只靠 Script_VoiceEncode 算出来的时长去撑 d，但那有两个漏洞：清单是
// 异步 fetch 来的，开场头一两行往往在它到达之前就已经开始跑了；而 141 条
// 里有 111 条配音比剧本写的 d 长，最多的超 5 秒。于是"话没说完就切镜"。
// 直接问播放器有没有念完，这两个洞一起堵上。
let VOICE_BUSY = null;
export function SetVoiceGate(fn) { VOICE_BUSY = fn; }
// 万一 promise 卡住（文件 404、解码失败），最多多等这么久就往下走
const VOICE_WAIT_CAP = 14;
function LineHeld(line, t) {
  const d = LineDuration(line);
  if (t < d) return true;
  if (t > d + VOICE_WAIT_CAP) return false;
  return !!(VOICE_BUSY && VOICE_BUSY());
}
export function LineDuration(line) {
  if (!VOICE_DUR) return line.d;
  const text = line.say || line.stage;
  if (!text) return line.d;
  const v = VOICE_DUR.get(VoiceLineId(line.say ? (line.who || "") : "", text));
  return v ? Math.max(line.d, v + 0.35) : line.d;
}

// ---------------------------------------------------------------------------
// 过场的一把尺子（2026-08-17 加，给 Script_CineTimeline 的时间轴面板与 CLI 共用）
//
// 过场里"现在演到哪儿"只有一个说法：**第几句、句内第几秒**——`shot` 子命令的
// `@line=N,at=T` 认的就是它。时间轴上的秒数是从它折算出来的（每句起点＝前面
// 各句时长之和，时长走 LineDuration：开着声音时被配音撑长的那份也算进去），
// 反过来拖播放头也是先换算回 (line, at) 再推游戏。两边共用这一处，免得
// 面板上一套、命令行一套，对不上号。
// ---------------------------------------------------------------------------
/** 各句的起点与时长：{ rows:[{start,d}], total } */
export function CineTimeTable(lines) {
  const rows = [];
  let acc = 0;
  for (const l of lines || []) {
    const d = Math.max(0, LineDuration(l) || 0);
    rows.push({ start: acc, d });
    acc += d;
  }
  return { rows, total: acc };
}

/** 眼下演到哪儿：{ id, chapter, beatIndex, kind, line, lineT, micro, lines }。
 *  微过场在跑时以它为准（同 TunnelLight.SeekLine 的口径）；不在过场里 line 为 null。 */
export function CineLocator(state) {
  if (!state) return null;
  const def = CurrentBeatDef(state);
  const base = {
    id: def?.id || null, chapter: state.chapterIndex, beatIndex: state.beatIndex,
    kind: def?.kind || state.phase, phase: state.phase,
  };
  if (state.microCine) {
    const mc = state.microCine;
    return { ...base, micro: true, line: mc.i ?? 0, lineT: mc.t || 0, lines: mc.lines };
  }
  if (def?.kind === "cinematic" && state.beat) {
    return { ...base, micro: false, line: state.beat.lineIndex, lineT: state.beat.lineT || 0, lines: state.beatLines || def.lines || [] };
  }
  return { ...base, micro: false, line: null, lineT: 0, lines: [] };
}

/** `c1_thatday@line=5,at=1.20`——shot 子命令吃的定位串；不在过场里就只有拍名 */
export function CineLocatorString(state) {
  const L = CineLocator(state);
  if (!L || !L.id) return "";
  if (L.line === null) return L.id;
  return `${L.id}@line=${L.line},at=${(L.lineT || 0).toFixed(2)}`;
}

// ---------------------------------------------------------------------------
// 谜题动词层（v0.3 关卡重做）：单格物品栏 / 投掷 / 狗 / 灯光 / 声响引敌
// 《勇敢的心》的关卡语法：每个障碍缺一样东西，东西在别处；石子落地出声；
// 狗认吃不认人；灯有周期。动词凑齐了，关卡才有"想一下"的时刻。
// ---------------------------------------------------------------------------
// 翻越：撑上顶沿 → 收腿荡过去 → 落地缓冲。比一步慢，慢到看得清是"手脚并用"，
// 又不至于打断走路的节奏。手里拎着东西得先把东西撂上顶沿，所以更慢一档。
const VAULT_DUR = 0.62;      // 齐胯高的墙一撑就过，拖长了就成了慢动作
const VAULT_DUR_BIG = 1.05;

// 上下梯子。井有 3.6 米深（SURFACE_Y→UNDER_Y）。**梯子上是自己爬的**（2026-08-17
// 用户："可以支持在半路停下的，就像勇敢的心那样"）：按住 S 往下、W 往上，松手就停在
// 那一档上，中途可以掉头。速度按人爬梯子的真速度给：下去顺着重力快些，上来是费力气
// 的活。高度由 p.lift 插值（见 MovePlayer 里的爬梯分支），不是换个层数就完事。
// 扶稳门扇（第一场"修门"）。下门轴跳出臼窝，整扇吊在上轴上自己往外坠；
// 玩家的手真的按在门板上，把它顶回门框正位，爹才使得上劲礅轴。
// 数值都按一扇 1.83m 高、0.83m 宽的木门给。
const DOOR_H = 1.50;         // 门扇高（米）＝ 手能按到的那一片有多长（对齐门框净空）
const DOOR_SAG = 0.26;       // 撒手之后它歪到哪儿（弧度，约 15°，下沿外坠 0.47m）
// 容差按"门下沿允许晃多少"定：±0.10 弧度 ≈ 下沿 ±18cm。
// 别定得比操作还细——上一版 0.055 配一个凭空的换算臂，等于要玩家按像素对准。
const DOOR_TOL = 0.10;
const DOOR_GRAB_R = 0.62;    // 手落在门板上的判定半宽（半扇门 + 一点富余）
// —— 门的分量（2026-08-09 用户退回「一点重量感也没有」，从跟手运动学改成真动力学）——
// 门有角速度、有惯性；重力永远在把它往外拉，手给的是一个**有上限的**对抗力。
// 于是：撒手是越坠越快的，不是匀速滑走；接住一扇正在坠的门，它还会带着你的手
// 沉半拍才停；把它从磕框的位置推回正位，是在跟它的分量较劲，快不起来。
const DOOR_G = 1.15;         // 重力角加速度尺度（rad/s²）
const DOOR_BIAS = 0.32;      // 轴歪出来的常量分量：立得再正它也不肯自己站住
const DOOR_HAND = 2.6;       // 手最大能给的角加速度（攥在门下沿、力臂最长时）
const DOOR_SPRING = 26;      // 手的"弹簧"刚度：门追手位，但隔着自己的分量追
const DOOR_DAMP = 7.5;       // 攥住时的阻尼——接坠门时吃掉动量的就是它
const DOOR_KICK = 0.55;      // 爹每礅一下轴，震劲顺门框传上来，门往外弹的角速度
const DOOR_SEAT_N = 4;       // 礅几下轴才咬进臼窝（进度按下数走，不按秒表走）
const DOOR_KEY = 0.42;       // 键盘后备：按住 E 把门扶正的角速度
// 这一拍必须推特写：默认跟随景别 12.6m 宽，一扇 0.83m 的门在手机上才 55 像素，
// 又是"要按住它、还要稳住"的活——按不着也稳不住（刨子那次就是这么被退回的）
// 这一拍的主体是**门脚下那根轴和它要礅进去的臼窝**，不是整扇门：机位钉在
// 膝盖那么高（0.72m）而不是胸口——1.15m 那一版把轴正好压在屏幕底部那条提示条
// 底下，玩家一整拍都没看见自己在修什么（用户 2026-08-10）
const DOOR_CAM = { y: 0.72, hw: 2.45 };

// 速度按"一档一档爬"给（2026-08-17 爬梯重做）：0.40m 一档，下 1.35m/s ＝每档 0.3 秒，
// 每只脚隔一档跨一步、四肢轮着动还看得清；上来费劲，慢一档。老版是定时 1.5 秒滑到底，
// 每档 0.14 秒，手脚再怎么钉在横档上也是一团糊。
const CLIMB_SPEED_DOWN = 1.35;
const CLIMB_SPEED_UP = 1.10;
const CLIMB_ACCEL = 14;             // 松手/按下的加减速（1/s）：停得干脆，又不是一格一格顿
const LADDER_RUNG = LADDER.pitch;   // 横档间距：每挪过一档响一声，声音跟着人走（与画笔/骨架同一张表）

// 层数**一按下就翻成目的层**（碰撞/视线/玩法一律按目的层算，不留半层的中间态），
// 渲染高度另走 p.lift 从原来那层缓过去。两件事分开，玩法才不会出现"半层人"。
// 中途掉头爬回原来那头出去的，出去那一刻再翻回来。
// 窖口上有盖板：一块抹了泥灰做旧的旧门板（正是 c1_plane 刨出来的那块）。
// 上下地道不是"人从地面沉下去"，是**掀开盖板 → 爬 → 把盖板拉回来盖上**：
//   p.climb = { id, y（脚线的世界 y）, v（竖向速度）, dir（最近一次爬的方向 ±1）,
//              phase: "open" | "ride" | "shut", t（open/shut 的计时）, fromTop, rung }
// `p.climbT` 只是给老读者留的旗（Main 的镜头、World 的 climbing、CLI）：在梯子上＝1。
const LID_OPEN = 0.45;       // 掀开：土封的边先崩开，板子立起来
const LID_SHUT = 0.50;       // 盖回：从底下伸手够着拉，比掀开慢一点

function StartClimb(state, toLevel, shaftId) {
  const p = state.player;
  const fromY = p.level === "under" ? UNDER_Y : SURFACE_Y;
  const destY = toLevel === "under" ? UNDER_Y : SURFACE_Y;
  p.level = toLevel;
  p.climb = {
    id: shaftId || null, y: fromY, v: 0, dir: destY < fromY ? -1 : 1,
    phase: "open", t: LID_OPEN, fromTop: fromY > destY, rung: 0,
  };
  p.climbT = 1;
  p.lift = fromY - destY;
  p.moving = false;
  p.crouch = false;           // 梯子上不猫腰：进地道那一下的弓背等落地再说
  p.pose = null;              // 手上的活到梯子这儿一律让位给爬的姿势
  // 从这一帧起镜头交给 lift（BaseShot 读它一档档跟着人下去）：窖口探头当场让位，
  // 不然这一帧两个来源叠着压，画面会先多沉一下再弹回来
  state.cellarPeek = 0;
  // 盖板归渲染层读：id 说是哪个窖口，open 是 0..1 的掀开量
  state.lid = { id: shaftId || null, open: 0 };
  Cue(state, "dig", { gain: 0.34 });        // 土封的边崩开，先是一下刮土
}

/** 梯子上的一帧：掀盖 → 自己爬（可停可掉头）→ 到头盖回。返回 true = 这一帧人在梯子上 */
function StepClimb(state, input, dt) {
  const p = state.player;
  const c = p.climb;
  if (!c) return false;
  const groundOf = (lv) => (lv === "under" ? UNDER_Y : SURFACE_Y);
  if (c.phase === "open") {
    c.t = Math.max(0, c.t - dt);
    if (state.lid) state.lid.open = 1 - c.t / LID_OPEN;
    if (c.t <= 0) c.phase = "ride";
  } else if (c.phase === "ride") {
    // 竖推：S(+1) 往下、W(−1) 往上；松手停在这一档，可以掉头
    const push = Math.abs(input.climb || 0) > 0.05 ? Math.sign(input.climb) : 0;
    const want = push > 0 ? -CLIMB_SPEED_DOWN : push < 0 ? CLIMB_SPEED_UP : 0;
    c.v += (want - c.v) * Math.min(1, dt * CLIMB_ACCEL);
    if (Math.abs(c.v) < 0.02 && !push) c.v = 0;
    if (push) c.dir = push > 0 ? -1 : 1;
    const y0 = c.y;
    c.y = Math.max(UNDER_Y, Math.min(SURFACE_Y, c.y + c.v * dt));
    // 一档一档地响：按真正挪过的档发，不是定时循环——快慢都对得上，停下就不响
    const rung = Math.floor((SURFACE_Y - c.y) / LADDER_RUNG + 1e-6);
    if (rung !== c.rung && Math.abs(c.y - y0) > 1e-6) { c.rung = rung; Cue(state, "ladder", { gain: 0.42 }); }
    // 到头了（还在往那头推）：出梯子、把盖板拉回来。到哪头就是哪一层
    const atTop = c.y >= SURFACE_Y - 1e-6, atBot = c.y <= UNDER_Y + 1e-6;
    if ((atTop && push < 0) || (atBot && push > 0)) {
      p.level = atTop ? "surface" : "under";
      c.phase = "shut"; c.t = LID_SHUT; c.v = 0;
    }
  } else {
    c.t = Math.max(0, c.t - dt);
    if (state.lid) state.lid.open = c.t / LID_SHUT;
    // 板子落回洞口那一下闷响（只发一次）
    if (!c.shutCued && c.t <= LID_SHUT * 0.04) { c.shutCued = true; Cue(state, "drop", { gain: 0.55 }); }
    if (c.t <= 0) {
      p.climb = null; p.climbT = 0; p.lift = 0; state.lid = null;
      return true;
    }
  }
  p.lift = c.y - groundOf(p.level);
  p.climbT = 1;
  p.moving = false;
  return true;
}

// 翻越的抬升曲线：人真的离地，不是换个姿势平移过去。
// 峰值取障碍高度的七成左右——胯骨压过顶沿的那一下，脚正好在顶沿上方。
// 扛着东西那一档在顶上多待一会儿（撂下、跨过、再拎起），所以是带平台的弧。
// 横移的节奏：迈上去 → 绕着撑手转（几乎原地）→ 荡下去落地。
// 三段的比例决定了"撑"看不看得出来——中段挪得越少，手按在墙头这件事越明显。
function VaultTravel(k) {
  if (k < 0.34) return 0.40 * Math.pow(k / 0.34, 1.5);          // 迈上去、手够住顶沿
  if (k < 0.66) return 0.40 + 0.18 * ((k - 0.34) / 0.32);       // 绕着撑手转，人几乎不前进
  const u = (k - 0.66) / 0.34;
  return 0.58 + 0.42 * (u * (2 - u));                           // 腿过了顶沿，荡下去
}

// 抬升曲线（返回**绝对米数**，不再是障碍高度的倍数）。
//
// 这里被退回过两次，症结每次都一样：**对称的正弦弧＝抛物线＝跳跃**。
// 起跳、到顶、落下三段等时等距，读出来就是"蹦过去"，跟撑手翻越没关系。
// 撑手翻越的高度曲线是一条**带平台的梯形**：
//   ① 手按上顶沿、身子被撑起来（快，0.3 秒不到）
//   ② **停在顶沿高度**——这一段是全动作的题眼：手是支点，胯骑在墙头上，
//      腿从顶上扫过去。高度几乎不变，所以看得出他是"撑着"不是"飞着"
//   ③ 手一松，人比升起来时更快地落下去（重力不讲道理），落地屈膝卸力
// 另外峰值按 VaultLiftFor(top) 算绝对值（顶沿 + 余量 − 站立胯高），
// 不按顶沿的百分比：百分比会让矮障碍抬过头、高障碍抬不够，两头都不像。
function VaultArc(k, big, top) {
  const u = Math.max(0, Math.min(1, k));
  const peak = VaultLiftFor(top);
  // 扛着东西那一档：先把东西撂上顶沿，所以在顶上多骑一会儿
  const rise = big ? 0.30 : 0.30;
  const fall = big ? 0.72 : 0.64;
  if (u < rise) {
    // 撑起来：起手最猛（蹬地那一下），到顶沿收住
    const t = u / rise;
    return peak * Math.sin(t * (Math.PI / 2));
  }
  if (u < fall) return peak;                          // 骑在顶沿上，腿扫过去
  const t = (u - fall) / (1 - fall);
  return peak * (1 - t * t);                          // 松手，加速落下
}

// pickedT：拿起的时刻。E 既是拾取也是放下，没有这 0.35s 的窗口，
// 拾取那一下顺手就把东西又扔回地上了
function GiveItem(state, item) { state.player.item = { ...item, pickedT: state.time }; }
function CanFreeDrop(state) {
  const it = state.player.item;
  return !!it && state.time - (it.pickedT || 0) > 0.35;
}

// ---------------------------------------------------------------------------
// 落地道具：手里的东西随时可以放下（勇敢的心式）；放下的东西留在世界里，
// 头顶挂一枚图形气泡当提示，走近再按 E 拾回 / 交换。
// ---------------------------------------------------------------------------
const GROUND_PICK_R = 1.5;    // 拾取半径
const GROUND_HINT_R = 5.0;    // 悬浮提示可见半径
// ---------------------------------------------------------------------------
// 接绳（把断了的井绳和找来的麻绳接上）——打的是**单编结**（水手结）
//
// 这一拍被退回过三次，三条理由都写死在这儿：
// ① **绕圈是缠辘轳轴的动作，不是接绳的动作**（2026-08-08）。
// ② **在世界里做，谁也看不出那是在打结**（2026-08-10）——1.5m 半宽的井口特写
//    下整个结才 0.23m，八分之一个画宽。所以搬上了铺满画框的活卡。
// ③ **穿一下、再拽三下，那压根不是个结**（2026-08-10 用户：「井里绳子打结的
//    打结玩法一点都不符合直觉 哪有打结是这样的」）。说得对：绳头从一个圈里
//    穿过去再拽，一拉就出来了，什么也没打上。老版还把"勒紧"拆成倒手拽三把
//    ——现实里勒紧是**一把连着拽到底**，倒手三次是游戏味儿，不是绳的味儿。
//
// 现在打的是真结。两根粗细不一样的绳要接，庄稼人打的就是**单编结**
// （sheet bend／水手结）：粗绳折个弯，细绳从弯里穿上来、绕过两股的背面、
// 再从自己那一股底下掖出去，最后一把勒死。粗细不同也咬得住，正是这儿的情形
// （井绳粗、找来的麻绳细）。全过程是**一条连贯的路**，手不用倒，
// 五个关口都是"这一下手往哪儿走"，没有一处是抽象的量：
//
//   ①口   从下面塞进弯口          ②上   从两股中间钻出来
//   ③背   绕到两股背后（左边）     ④底   从底下兜回右边
//   ⑤掖   从自己那一股底下掖出来   → 一把勒到底
//
// 顺带一条真事儿：单编结打完，**两个绳头得在同一侧**——不在同侧那是"左手
// 单编结"，吃劲就松。所以麻绳从右下角进画，掖完绳头也甩在右上，和井绳
// 那个断头一边儿。
//
// 坐标一律用「卡宽」单位：x ∈ 0..1，y ∈ 0..1/aspect（＝卡高）。指针落点
// (pointerCard.u, .v) 换算成这套坐标是 { x: u, y: v / aspect }。
// **判定与作画共用这一份**，Art 里绝不许另抄一套。
export const KNOT_CARD = {
  aspect: 16 / 9,
  // 井绳：折回来的那个弯（U 的闭口端在左，开口朝右），两股往右岔开
  bend: { x: 0.215, y: 0.290, r: 0.074 },
  legUp: [{ x: 0.215, y: 0.216 }, { x: 0.44, y: 0.172 }, { x: 0.66, y: 0.112 }, { x: 0.80, y: -0.08 }],
  legLow: [{ x: 0.215, y: 0.364 }, { x: 0.44, y: 0.392 }, { x: 0.645, y: 0.402 }],
  anchor: { x: 1.06, y: 0.505 },          // 麻绳从画框右下角进画的那一点
  start: { x: 0.82, y: 0.440 },           // 麻绳头的起手位置
  // 五个关口，**必须按顺序过**：跳着走不算数（那就不是这个结了）。
  // 关键的是三、四两道：**绕的是那两股，不是那个弯**。绕着弯的闭口兜一圈，
  // 绳圈会顺着弯滑到开口那头脱出去——那不叫结，叫套着。绕住两股再掖住自己，
  // 一吃劲两股就把麻绳咬死，这才是单编结管用的地方
  gates: [
    { id: "mouth", x: 0.335, y: 0.294, r: 0.086, hint: "从下面塞进弯口" },
    { id: "up", x: 0.302, y: 0.120, r: 0.080, hint: "从两股中间钻上来" },
    { id: "over", x: 0.585, y: 0.130, r: 0.084, hint: "贴着上股往右挪" },
    { id: "back", x: 0.560, y: 0.470, r: 0.090, hint: "绕到两股背后兜下来" },
    { id: "tuck", x: 0.175, y: 0.212, r: 0.080, hint: "从自己那股底下掖出去" },
  ],
  grabR: 0.088,                           // 攥得住绳头的判定半径
  slipR: 0.170,                           // 手飘离绳头这么远就脱手
  speed: 0.95,                            // 绳有分量：一秒最多跟着手走这么多卡宽
  cinchSpeed: 0.13,                       // 勒紧那一把慢得多——**结在咬**，绳一寸一寸地走
  // 绳就这么长（绳头离锚点最远到这儿）。**这个数要留得住勒紧那一把的行程**：
  // 从最后一道关口沿 cinch 方向还得走得完 cinchLen，不然绳头会先被绳长卡住，
  // 剩下那点进度全靠贴着圆弧蹭——实测过一次，一把变成了四秒半的磨。
  reach: 1.18,
  // 勒紧往左上拽：麻绳的另一头在右下角，**两头一拽**结才咬死
  cinchTo: { x: 0.060, y: 0.118 },
  cinchLen: 0.17,                         // 一把要拽走这么多卡宽，结才勒死
  cinchBack: 0.34,                        // 撒手就往回泄（半截的结自己会松）
};

const KnotD = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);

/** 勒紧的单位方向（结心 → cinchTo）。判定与作画共用 */
export function KnotCinchDir() {
  const L = KNOT_CARD;
  const dx = L.cinchTo.x - L.bend.x, dy = L.cinchTo.y - L.bend.y;
  const d = Math.hypot(dx, dy) || 1;
  return { x: dx / d, y: dy / d };
}

/** 走到第 i 关时绳头该在哪儿（作画的折线、驱动器的落点共用） */
export function KnotWaypoint(i) {
  const L = KNOT_CARD;
  const g = L.gates[Math.max(0, Math.min(L.gates.length - 1, i))];
  return { x: g.x, y: g.y };
}

// ---------------------------------------------------------------------------
// 叠衣裳 · 裹包袱（第一章夜里下窖，归置爹娘的东西）
//
// 这一拍原来是两句「E · 归置家什」「E · 摆正笸箩」——长按 E 等它走完，人杵在
// 窖里，画面上什么都没发生。全作拟物标准第 0 条禁的正是这个，第 7.5 条禁的
// 是紧跟着那句「E · 放下去」。这是第一章情绪最重的一场（全程没有一句台词、
// 一条手记），却是唯一一场手上没有活的。
//
// 尺度量过，结论和石笔/刨子/接绳同源（CLAUDE.md 拟物交互第 4 条）：地窖的
// 玩法机位半宽 8.0m，一件褂子摊开才 0.55m ——十四分之一个画宽，比接绳那个结
// 还小。**手指按不着、认不出的东西，推镜头治不好**，所以这一拍长在一张铺满
// 画框的手绘活卡上（`state.foldCard` → `Art.DrawFoldCard`）。
//
// 四下手，一件一件来，全是人人做过的动作：
//   ① 揭草苫——爹娘的东西打扫荡那天起就盖在苫子底下没人动。攥住苫角往怀里
//      掀；东西压在上头，掀到位还得**再抻一把**才整个揭得下来（cinch）。
//      这一下最沉、行程最长，后面三下一下比一下轻——手感自己会说话。
//   ② 两袖交叠（短横）③ 顺肩线对折（长横）④ 拦腰折上来（竖）。
//      **折到最后一下，襟里子翻出来，那片干成褐色的印子正冲着油灯**——
//      这一镜不是走到某个点触发的，是玩家自己的手翻出来的。手撒开，卡停住
//      两秒半（第 2 条：那量的是时间，不是功，所以它是演出不是进度）。
//
// 判据四条，缺一不可（第 0 条）：①按下那一帧手必须落在**那个角**上；②布有
// 分量（跟手走但有速度上限）；③手甩离布角就脱手，那一折**弹回原处**重来；
// ④反馈全长在布上（折痕、越叠越小、印子翻出来），HUD 上一根条都没有。
//
// 坐标同接绳，一律用「卡宽」单位：x ∈ 0..1，y ∈ 0..1/aspect。指针落点
// (pointerCard.u, .v) 换算成这套坐标是 { x: u, y: v / aspect }。
// **判定与作画共用这一份**，Art 里绝不许另抄一套。
// 卡高＝1/aspect＝0.5625 卡宽。版面自上而下：窖壁一条（0~0.118）、窖底、
// 一领草苫摆在当中、油灯在左前角。**苫子不许铺满画框**——铺满了它就成了背景，
// 玩家看不出那是一件盖在东西上的物件（刨子那次的教训：认不出＝没做）。
export const FOLD_CARD = {
  aspect: 16 / 9,
  wall: 0.118,       // 窖壁与窖底的交界（作画用）
  lamp: { x: 0.108, y: 0.208 },   // 豆油灯搁在左前角的地上：这张卡唯一的光源
  // 草苫（东西摊在上头）：卡宽单位的矩形
  mat: { x0: 0.150, y0: 0.148, x1: 0.858, y1: 0.500 },
  // 摊开的褂子：肩线、下摆、两袖袖口，作画按这几个数长出来。
  // **身子要比袖展窄、比它自己高**——第一版身子 0.444 宽只有 0.256 高，摊出来
  // 是一床褥单不是一件褂子
  shirt: { x0: 0.330, x1: 0.670, shoulderY: 0.176, hemY: 0.464, cuffL: 0.238, cuffR: 0.762 },
  // 盖在上头那领破麻苫：**比褂子窄一圈**，好让右边一只袖口、底下一截下摆
  // 露在外面——"底下压着东西"这件事得看得见，不能光靠玩家猜
  cover: { x0: 0.286, y0: 0.150, x1: 0.700, y1: 0.436 },
  grabR: 0.082,      // 攥得住那个角的判定半径（1600px 宽的卡上＝131px）
  slipR: 0.152,      // 手甩离布角这么远就脱手，那一下弹回原处
  speed: 0.74,       // 布有分量：一秒最多跟着手走这么多卡宽
  tol: 0.058,        // 落点容差：进了这个圈这一下就成了
  linger: 2.5,       // 最后一折之后卡停在那儿的秒数（那片印子的一镜）
  // 四下手。from＝拈起来的那个角，to＝该把它放到哪儿；cinch＝到位之后还得
  // 顺着这股劲再抻这么长（只有揭苫那一下有）。
  folds: [
    { id: "mat", from: { x: 0.692, y: 0.428 }, to: { x: 0.226, y: 0.462 }, cinch: 0.072,
      say: "攥住苫角，往回掀——东西压着，得再抻一把" },
    { id: "sleeves", from: { x: 0.244, y: 0.250 }, to: { x: 0.478, y: 0.284 },
      say: "两只袖子交叠着掖到身前" },
    { id: "half", from: { x: 0.338, y: 0.428 }, to: { x: 0.596, y: 0.408 },
      say: "顺着肩线，把左半幅盖过右半幅" },
    { id: "hem", from: { x: 0.560, y: 0.462 }, to: { x: 0.564, y: 0.258 },
      say: "拦腰对折，下摆翻上来" },
  ],
};

const CardD = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);

// ---------------------------------------------------------------------------
// 找吃的：翻烧塌的牲口棚（第一章第一场玩法，2026-08-12 重做）
//
// 老版是三步一模一样的 `use + hold`：站在那儿按住 E，外面套一圈进度环，
// 三处的分别只有提示上那四个字（翻开苫草／挪开门板／刨开烧土）。用户原话：
// 「找吃的这里的动画以及交互方式居然是长按一个按钮？一点都不拟物，交互程度
// 低，一点也不沉浸」——说得对，而且它正撞在 CLAUDE.md「拟物交互」第 0 条上。
//
// 现在是**四道手，四个不重样的动词**（长度与打水那一场同源：加长靠加道数，
// 不靠把一道拉长）：
//   ① **掀**苫草——攥住焦草苫子的外沿，绕当中那条折痕把它折过去。苫子有分量
//      （跟手走但有角速度上限），撒手它自己坠回来；烧脆的草**手甩得比它快就撕**。
//   ② **拖**门板——攥住露在外头的那一头往回拖。板子沉、跟地蹭出吱嘎；拖到
//      半道**板头卡在焦椽茬上**，得往回让一寸再拖，它才让过去。人一边退一边拖。
//   ③ **扒**烧土——手落在土堆上，一把一把往自己怀里扒。一把够长够斜才算一下，
//      每一下土堆真矮一截；扒到第三下指头碰着硬的——罐肩露出来了。
//   ④ **解**扎口——罐口拿一块蓝底白花的碎布蒙着、麻绳绕了三道（2026-08-12
//      用户改稿钉死：这块布是娘那件短褂上的，跟夜里窖角埋掉的那件同一块——
//      暗线的两头都在玩家手上）。指尖上的活，长在一张铺满画框的活卡上
//      （同石笔/刨子/接绳）：捏住绳头**逆着缠的方向**一道一道褪，
//      再捏住布角掀开。娘扎的口，玩家亲手拆开——这一章的题眼落在这一下。
//
// **2026-08-17 输入整个换掉（用户：「还有分红薯、打开糊在罐头上的泥巴等非按 E 的
// 复杂交互存在，帮我改掉，改得更贴切一些」）**：指针攥拖／虚拟指尖那一整套下线，
// 这几件东西全部只认四动词——掀＝按住 E＋↑、扒＝按住 E＋↓、抹＝按住 E＋←→、
// 抠泥＝按住 E＋↑。分量还在（角速度上限、撒手坠回、第三把钉住），只是手不再
// 由指针给位置，而是由方向键给"使劲"。驱动器走通用的 holdAt＋stroke，不再各配
// 一条拖拽路。下面表里 grabR / keepR / slipA 那几个指针时代的数只有画笔还在读。
//
// 尺寸都是按"认得出"倒推的（CLAUDE.md 第 4 条：实际尺寸 ÷ 画宽 < 1/10 就别指望
// 玩家认得出）。玩法景别画宽 8.7m（2026-08-14 收了一档，原 12.3m）：苫子
// 1.6m＝18%、门板 1.5m＝17%、土堆 1.2m＝14%——三样都过线，所以它们留在世界里，
// 只有罐口那道扎口（0.2m 出头，2%）非推特写不可，于是它是唯一一张活卡。
// ---------------------------------------------------------------------------
export const FORAGE = {
  // ① 苫草：**搭在塌下来的椽子上、当中折着**的一片焦草苫子，绕折痕折过去。
  // 两条都是实拍逼出来的：
  //   · 折痕要**架起来**（pivotY 0.5m）。平摊在地上的一片苫子在侧视里只有
  //     十来个像素高，跟地上的影子分不开——实拍第一版就是"人对着一摊黑影
  //     伸手"。架起来之后剪影 1.14×0.50m（屏幕上 148×65px），一眼是块东西。
  //   · 外沿的起手位置抬到 0.23m（restA −0.40），别贴着地。贴地的话孩子
  //     那条 0.39m 的胳膊够不着（CLAUDE.md 第 10 条那笔账），手会停在半空。
  mat: {
    half: 0.70,        // 半幅：折痕到外沿。整片 1.4m
    pivotY: 0.50,      // 折痕架在瓦砾上的高度
    restA: -0.40,      // 歇息角（外沿斜搭下来，离地 0.23m）
    westA: -2.35,      // 压在底下那半幅的角度（西边，落到地上）
    grabR: 0.44,       // 攥住外沿的判定半径
    slipA: 0.55,       // 手比苫子超前这么多弧度 = 焦草撕开、这一把作废
    speed: 2.0,        // 苫子有分量：一秒最多跟着手转这么多弧度
    lift: 1.05,        // 按住 E＋↑ 一秒抬这么多弧度（歇息角到重心 1.7rad ≈ 一秒半）
    fall: 2.2,         // 撒手它自己坠回去（重力力矩 ∝ cos）
    tipAt: 1.30,       // 过了这个角就过了重心，自己翻到西边去
    standGap: 0.42,    // 手在外沿上，人就站在外沿外头这么远（一臂之内）
  },
  // ② 门板：横着拖，摩擦 + 一处卡口。**东头架在食槽上**（tilt），所以它在
  // 侧视里是一块斜着的板，不是地上一条线；拖出去的过程中那一头慢慢落下来，
  // 拖到头"咚"地拍在地上——"板子底下是半截食槽"这句话由画面自己说
  plank: {
    len: 1.50,
    westDx: -1.00,     // 板子西头相对判定区中心
    tilt: 0.22,        // 架在食槽上的仰角（东头离地 0.33m，正好一伸手）
    grabR: 0.44,
    need: 1.00,        // 拖出这么远才算挪开
    speed: 0.85,       // 板子沉：一秒最多蹭这么远
    push: 0.42,        // 按住 E＋→ 一秒推这么远（沉：比手拖还慢一档）
    snagAt: 0.42,      // 拖到这儿板头卡在焦椽茬上
    snagBack: 0.16,    // 往回让这么多，才让得过去
    standGap: 0.55,
  },
  // ③ 灰堆（2026-08-15 重做。用户对老版的原话：「手插进灰堆的玩法太愚蠢了
  // 既没有代入感 也不好玩 也没有解密感」——老版是同一个手势重复五把，第三把
  // 弹一条 toast 说碰到坛肩：发现时刻是**字幕说的**，不是手感觉到的）。
  // 现在这一堆分三层，每层的手感不一样，剧本那句「第一下是灰、第二下露硬土、
  // 第三下指甲碰到陶器」逐字长在手上：
  //   第一把 浮灰——轻，一把很快就下去（strokeS[0]）；
  //   第二把 硬土——拖不快（strokeS[1] 长一倍多），分量全在阻力里；
  //   第三把 拽到半道**手钉住**（catchAt）：一声闷响、灰扑起来，这一把永远
  //   拉不完——指甲碰上坛肩了。不上屏一个字。
  // 钉住之后「往怀里扒」这个动词就死了：再拽只有闷响。出路是**换方向**——
  // 贴着那个硬东西横着抹（wipes，按住 E＋←/→），一把带走一片土，坛肩抹哪儿露
  // 哪儿。**2026-08-17 起提示会直接换成「顺着坛肩把土抹开」**（四动词口径：
  // 换了动词就换键帽，不再让玩家自己猜方向），解密感留在"第三把突然钉住"那一下。
  ash: {
    half: 0.60, top: 0.50,
    grabR: 0.80,       // 手要落在土堆上（画笔/招呼圈还在读）
    keepR: 1.25,
    len: 0.26,         // 一把扒多远（姿势/挂点按它换算）
    skew: 0.80,
    digs: 2,           // 真扒进度只有头两把：浮灰一把、硬土一把
    strokeS: [0.55, 1.25, 0.9],   // 按住 E＋↓ 一把要多久：浮灰快、硬土慢、第三把（钉住前）
    looseV: 1.9,
    packedV: 0.55,
    catchAt: 0.60,     // 第三把拽到 len 的这个比例，指甲碰上坛肩，手钉住
    pinHold: 0.40,
    knockEvery: 0.7,   // 钉住之后还往怀里拽：每这么久一声闷响（拽不动）
    jarDx: -0.08,      // 坛肩埋在堆心偏西这点（判定与作画共用）
    shoulderY: 0.16,   // 坛肩顶离地这么高（钉点、抹土的圈都锚在这儿）
    wipeR: 0.46,       // 抹土时手要贴着坛肩这一圈
    wipes: 3,          // 顺着坛肩抹这几把，肩一段段露出来
    wipeLen: 0.17,     // 一把抹多远（挂点按它换算）
    wipeS: 0.55,       // 按住 E＋←/→ 一把要多久
    wipeSkew: 0.42,
    standGap: 0.90,
  },
  // ④ 苇席（第七稿新增）：机制同苫草，但席子轻、没烧脆——甩快了只脱手，
  // 不撕（slipA 给到不可能触发的大数；撕是焦草的性子，不是苇子的）
  reed: {
    half: 0.62,
    pivotY: 0.42,
    restA: -0.42,
    westA: -2.30,
    grabR: 0.42,
    slipA: 9.0,        // 苇席不撕：这个门槛永远够不着
    speed: 2.4,        // 比苫草轻快一档
    lift: 1.25,        // 按住 E＋↑：苇席轻，抬得比苫草快一档
    fall: 2.0,
    tipAt: 1.28,
    standGap: 0.40,
  },
  // ⑤ 食槽（第七稿新增）：机制同刨灰，件小、下数少——槽底那层秕谷壳
  // 一把一把扫进兜里。就这么点。
  trough: {
    half: 0.50, top: 0.30,
    grabR: 0.62,
    keepR: 1.00,
    strokes: 3,
    strokeS: [0.5, 0.5, 0.5],   // 按住 E＋↓ 一把要多久（三把一样：槽底下没埋东西）
    len: 0.20,
    skew: 0.80,
    jarAt: 0,          // 槽底下没有坛子
    standGap: 0.72,
  },
};

/** 苫草/苇席外沿此刻在哪（判定、作画、驱动器共用这一份） */
export function ForageMatEdge(zoneX, groundY, ang, part) {
  const L = FORAGE[part || "mat"];
  return {
    x: zoneX + Math.cos(ang) * L.half,
    y: groundY + L.pivotY + Math.sin(ang) * L.half,
  };
}

/** 门板东头（玩家攥的那一头）此刻在哪：架在食槽上，拖出去的过程里慢慢落下 */
export function ForagePlankEnd(x0, groundY, dx) {
  const L = FORAGE.plank;
  const tilt = L.tilt * Math.max(0, 1 - dx / L.need);
  return {
    x: x0 + L.len * Math.cos(tilt) + dx,
    y: groundY + L.len * Math.sin(tilt),
    tilt,
  };
}

/** 扒土的方向：朝自己、往斜下（dirX = 人在土堆的哪一边） */
export function ForageScoopDir(dirX) {
  const d = Math.hypot(0.86, 0.50);
  return { x: (dirX || 1) * 0.86 / d, y: -0.50 / d };
}

// ---------------------------------------------------------------------------
// 坛口那圈泥（活卡版面，第七稿改稿：泥圈＋半块碗底，不再是绳扎口）。
// 坐标同 KNOT_CARD：卡宽单位 x∈0..1、y∈0..1/aspect。**判定与作画共用这一份**，
// Art 里绝不许另抄一套。
//
// 两段动作，都是人人做过的，**输入只有一个：按住 E ＋ ↑**（2026-08-17 四动词
// 重排——用户点名「打开糊在罐头上的泥巴」不该是复杂交互）：
//   ① **抠泥**：指头抵着坛口那圈干泥往上抠，一段一段啃过去（三箍，unwindS 秒）。
//      屏幕上指头顺着圈逆时针走，泥真的一块一块掉、渣攒在坛肩上。松手泥不长回去。
//   ② **揭碗片**：泥落了，同一个键继续——碗片翘起来（peelS 秒）；松手它压回去。
//      碗片底下垫着一圈蓝底白花的碎布——暗线的第二面。
// ---------------------------------------------------------------------------
export const WRAP_CARD = {
  aspect: 16 / 9,
  neck: { x: 0.50, y: 0.300, r: 0.168 },   // 坛口（糊着泥的那一圈）
  laps: 3,                                  // 泥圈分三箍，抠松要绕这几圈
  gap: 0.42,                                // 起手位那个豁口的弧度（本来就缺一块）
  unwindS: 3.0,                             // 按住 E＋↑ 抠完三箍要这么久
  peelS: 1.1,                               // 揭开碗片要这么久
  peelFall: 0.7,                            // 松手碗片压回去的速度（open/秒）
  tip: { x: 0.735, y: 0.250 },              // 起手抠的那个豁口
  grabR: 0.105,                             // 画笔：招呼圈的半径
  cloth: { x: 0.352, y: 0.214 },            // 揭碗片时捏的那道边（坛口西北）
  peelTo: { x: 0.06, y: 0.47 },             // 往这边揭（左下）
  peelLen: 0.30,                            // 揭过这么远，碗片整个起开了
};

/** 抠泥抠到哪儿了：卡坐标里指头此刻抵着的角度（起手豁口起、屏幕逆时针数）。判定与作画共用 */
export function WrapEdgeAngle(lapK) {
  const L = WRAP_CARD;
  const c = L.neck;
  const tipA = Math.atan2((L.tip.y - c.y) / 0.42, L.tip.x - c.x);
  return tipA - L.gap - Math.max(0, Math.min(1, lapK)) * (Math.PI * 2 - L.gap);
}

/** 揭碗片的单位方向（碗片 → peelTo）。判定与作画共用 */
export function WrapPeelDir() {
  const L = WRAP_CARD;
  const dx = L.peelTo.x - L.cloth.x, dy = L.peelTo.y - L.cloth.y;
  const d = Math.hypot(dx, dy) || 1;
  return { x: dx / d, y: dy / d };
}

// ---------------------------------------------------------------------------
// 分食：掰红薯干（第七稿第一章第二场）。
//
// 泡软的红薯干一条 0.12m，玩法景别里不到 1% 画宽——同石笔/接绳/解扎口，
// 长在一张铺满画框的活卡上（state.splitCard → Art.DrawSplitCard）。
// 三下，**照 Notion 关卡设计第 6 拍的口径**（2026-08-17 四动词重排，用户点名
// 「分红薯」不该是复杂交互）：
//   ① **掰｜按住 E ＋ ← 或 →**：从你使劲那头断开——按左掐在偏左那点，断出来
//      左短右长；按右反过来。**掰哪儿断哪儿**这条手感留住了，只是捏点由方向定。
//      掰过一个弯它就断成两截（bendS 秒）；松手它慢慢直回来。
//   ② **分进两只碗｜E**：一按，他把两截分进两只碗——**长的那截搁进她碗里**，
//      短的留给自己（sortS 秒的卡上动画：一截一截搁）。
//   ③ **放回她碗里｜E**（她把长的推回来之后）：一按，把长的那截从自己碗里捞
//      出来，提在半空沥两滴，再搁回她碗里（swapS 秒的卡上动画）。
// 坐标一律「卡宽」单位：x ∈ 0..1，y ∈ 0..1/aspect。**判定与作画共用这一份**。
// ---------------------------------------------------------------------------
export const SPLIT_CARD = {
  aspect: 16 / 9,
  // 两只碗：西边她的、东边他的（画面上左她右他，跟屋里的站位一致）
  bowlL: { x: 0.295, y: 0.415, r: 0.095 },
  bowlR: { x: 0.705, y: 0.415, r: 0.095 },
  // 泡软的那条红薯干：两手举在碗上方，横着
  strip: { cx: 0.50, cy: 0.180, len: 0.240 },
  grabMin: 0.18, grabMax: 0.82,   // 捏点只认条上这一段（贴着两头掰不断）
  grabOff: 0.17,                   // 按 ←/→ 掐在离条心这么远（×len）：断出来一长一短
  grabR: 0.085,                    // 画笔：招呼圈的半径
  bendNeed: 0.115,                 // 往下掰过这个量它就断（卡宽单位的下压距离）
  bendS: 0.9,                      // 按住掰到断要这么久
  bendBack: 0.5,                   // 松手它直回来的速度（卡宽/秒）
  // 断出来的两截先落在两碗之间的案上
  restL: { x: 0.415, y: 0.335 },
  restR: { x: 0.585, y: 0.335 },
  tol: 0.065,                      // 搁进碗里的落点容差
  sortS: 0.75,                     // 分：一截搁进碗里走这么久（两截先后各一段）
  // ③ 放回去：提到这条线以上算「提在半空」，滴够两滴才算沥过
  liftY: 0.235,
  liftAt: { x: 0.52, y: 0.19 },    // 捞出来提到这儿沥水
  drips: 2,
  dripEvery: 0.42,
  swapS: [0.55, 0.9, 0.6],         // 放回去的三段：捞出来提起 / 沥两滴 / 搁进她碗
};

// ---------------------------------------------------------------------------
// 撕布（第八稿第一章·救人，活卡）。月光下，那块没下过剪子的整布摊在
// 草苫上——伤口压不住了，把它撕成条。
// 三把，都是人人撕过布的手感，**输入只有按住 E ＋ ←**（Notion 第 13 拍）：
//   ① **第一把**：横着往回拽——布只被**拉紧**（拽到头它不走了、弹回去，
//      这一把记下了）。
//   ② **第二把**：再拽到头，布边**裂开一道口**（裂口声）。
//   ③ **继续拽**：裂口顺着织纹跑，撕裂声一段一段——一条长布分离下来。
// 前两把拽到头之后布要**弹回去、缓一口**（recoilS）才能再拽——按住不放也是
// 一把一把的，不是一根越拽越长的条。坐标一律「卡宽」单位。**判定与作画共用这一份**。
// ---------------------------------------------------------------------------
export const TEAR_CARD = {
  aspect: 16 / 9,
  // 整布摊在画框中带（对折过，横着）；草苫在底下垫着
  cloth: { x0: 0.14, x1: 0.86, y: 0.205, h: 0.20 },
  // 抓的那个角（东上角），压在布的上沿里一指、画成一个真的翘起来的角（DrawTearCard）
  corner: { x: 0.795, y: 0.228 },
  grabR: 0.115,                    // 画笔：招呼圈的半径
  tautLen: 0.115,                  // 一把拖到这儿＝绷紧到头
  tautS: 0.7,                      // 按住拽紧一把要这么久
  recoilS: 0.35,                   // 拽到头弹回去、缓一口：这段时间再拽不算
  tearLen: 0.40,                   // 裂口之后累计再拖这么远＝整条撕下来
  tearS: 1.5,                      // 顺着裂口一路拽到头要这么久
  stripW: 0.075,                   // 撕下来那条的宽（作画用）
};

// ---------------------------------------------------------------------------
// 缝三针（第八稿第一章·缝，活卡）。蓝布条贴在旧褂袖口上，针别在领口——
// 三针把它接上：
//   ① 捏住针，送到接缝上**穿出**（第一针位置偏高——针脚落点由版面钉死，
//      玩家的手只负责"送到、拉线"，歪是这件事本身的歪）；拉线到头。
//   ② 第二针穿得偏低，两块布被拉出一道小褶。
//   ③ 第三针穿过旧布、蓝布再折回去，线头绕过针脚，拉紧（这一针的线
//      拉得最长）。
// 判据同全部活卡；坐标一律「卡宽」单位。**判定与作画共用这一份**。
// ---------------------------------------------------------------------------
export const SEW_CARD = {
  aspect: 16 / 9,
  sleeve: { x0: 0.26, x1: 0.575, y: 0.295, h: 0.115 },  // 旧褂袖筒（横着）
  patch: { x0: 0.575, x1: 0.78, y: 0.30, h: 0.105 },    // 蓝布条搭在袖口外
  seamX: 0.578,                                          // 接缝（竖着）
  // 三针：send=进针点（送针到这儿就穿出）、pull=拉线的落点、
  // off=针脚画出来的歪（正=偏低）；第二针 pucker（拉出小褶）、第三针 back（折回绕线头）
  stitches: [
    { send: { x: 0.578, y: 0.318 }, pull: { x: 0.70, y: 0.20 }, off: -0.014 },
    { send: { x: 0.582, y: 0.376 }, pull: { x: 0.71, y: 0.47 }, off: 0.016, pucker: true },
    { send: { x: 0.579, y: 0.349 }, pull: { x: 0.74, y: 0.30 }, off: 0.0, back: true },
  ],
  needle0: { x: 0.70, y: 0.44 },   // 针的起手位（线还连着笸箩那头）
  grabR: 0.095,
  slipR: 0.155,
  speed: 0.9,
  sendTol: 0.032,                  // 送针进点的容差
  pullTol: 0.035,                  // 拉线到位的容差
};

// ---------------------------------------------------------------------------
// 铺满画框的活卡一共这几张。**名单只有这一份**——新加一张就往这儿添一个词，
// 别在别的文件里手抄（`onLiveCard` 与 EdgeHint 各抄过一遍，后加的四张一张都
// 没跟上：撕布那一拍因此整幅卡当中常驻着一句「W · 上梯子」，玩家看见的唯一
// 一句指示指的是另一件事，2026-08-14 用户报的就是它）。
// ---------------------------------------------------------------------------
export const LIVE_CARD_FIELDS = [
  "scribeCard", "planeCard", "knotCard", "foldCard",
  "wrapCard", "splitCard", "tearCard", "sewCard",
];

/** 眼下有没有一张活卡铺在画框上（世界里的找路 UI、摇杆一律让位） */
export function LiveCardOn(state) {
  return LIVE_CARD_FIELDS.some((k) => !!state[k]);
}

// ---------------------------------------------------------------------------
// 拉耧（第七稿第一章·地头）。耧要一个人在前面拉、一个人在后面扶——
// 一个人拉，扶不住：走出两步，耧腿一歪，扎进垄沟里。再来一次。还是歪。
// **这一场的玩法就是它办不成**（全作唯一一处：交互的正确结局是失败——
// 因为它要说的话是「这块地，一个人耩不了」，七叔那句"明儿我把牲口牵过来"
// 就落在这儿）。
// 输入是走位本身（范式表最后一行：拖着一件有物理的东西走）：套上绳，往东走，
// 绳绷直了耧就跟上；到了 tryAt 那一步它自己歪进垄沟，把人拽停。
// ---------------------------------------------------------------------------
export const LOU = {
  gap: 1.7,            // 绳长：人在前面这么远，绳才绷直
  tryAt: [1.15, 1.95], // 两回各走到多远耧腿一歪（累计位移）
  tiltA: 0.42,         // 歪进垄沟的角度
};

// ---------------------------------------------------------------------------
// 辘轳转盘：鼠标绕摇把轴心转圈驱动（顺时针放绳、逆时针摇起）。
//
// **轴心高度按"够得着"倒推，不按"井架好看"倒推**（2026-08-10）。量过才知道
// 老版有多离谱：柱子头顶才 1.13m、肩高约 0.98m、一条胳膊伸直 0.46m，而轴心
// 定在 1.43m——比他头顶还高 30 厘米，摇把画的那个圈他一辈子也够不着。屏幕上
// 就是"人站在旁边空划拉、辘轳自己在转"，这正是"角色动作太蠢"的根。
// 这四个数是**一起**解出来的，三条约束夹在中间（实拍逐条撞出来的）：
//   ① 够得着：肩到轴心的距离 + 柄长 ≤ 臂长 0.392 + 姿势里那一档身位 0.06；
//   ② **摇把画的那个圈不许扫过他的脸**：圈的最左沿要让开脑袋（半宽 0.09）。
//      漏了这一条就会出现"举手过眉去够、整条胳膊横在自己脸前"——实拍裁下来
//      是"一只手捂着脸"，比够不着还难看；
//   ③ 轴心不许再低：井台沿 0.73 + 辘轳鼓半径 0.14 = 0.87，再低鼓就压在井口上
//      放不出绳。
// 解：站位 −0.76、轴心 0.9375、摇把在**靠人这一侧的端面** −0.44、柄长 0.12。
// 圈的最左沿 −0.56，脑袋右缘约 −0.63，让开 7 厘米；摇把最远那一点离肩 0.41m。
// World 那边把前手 IK 到握手上（手是真的攥着摇把在抡），并且把摇把**排在人
// 之前**——排在人之后的话，他一伸手就把摇把整个盖住了，画面上又变成空划拉。
// SmokeTest 的 TestWinchIsACrankNotALever ⑦ 逐点量这一圈。
// 改这几个数就要同步 `Art.DrawWell` 的 HUB（井架横杆高度）与摇把的画法。
export const WINCH_HUB_Y = 0.9375;     // ＝ DrawWell 的 groundY−45px（48 像素/米）
export const WINCH_CRANK_DX = -0.44;   // 摇把轴销相对井心的偏移（−21px，西端面＝摇的人这一侧）
export const WINCH_CRANK_R = 0.12;     // 柄长：握手绕轴心画的那个圈的半径（5.8px）
export const WINCH_STAND_DX = -0.76;   // 摇辘轳的站位（相对井心）
export const WINCH_REST_A = -0.6;      // 摇把的歇息角：静止时斜垂着，别跟横杆混成一根木头
// 一井绳要摇多少圈。2026-08-10 用户退回过一次：老版 1.6/2.6 圈、键盘全速
// 4.5 秒就拎着水走了——「太短了 一点仪式感也没有 ... 3x 差不多」。
// 加长**不是**只把这两个数乘三（同一个转盘拧更多圈只是变闷），是加道数；
// 这两个数跟着往上抬一档，四道手加起来才有分量。时长有单测钉着
//（Script_SmokeTest 的 TestWinchIsLongEnough）。
const WINCH_TURNS_DOWN = Math.PI * 2 * 3.2;
const WINCH_TURNS_UP = Math.PI * 2 * 4.6;
// ── 四道手里那两道不摇转盘的 ──
const WINCH_DUNKS = 3;            // 墩几下桶才肯扣过去吃水
const WINCH_DUNK_PULL = 0.16;     // 一墩要往下拽多少米才算数（拽得慢只是蹭水面）
const WINCH_ROPE_R = 0.16;        // 攥井绳的走廊半宽：手飘出这条线就脱手
const WINCH_STAM_DUNK = 0.07;     // 一墩额外掉的手劲
const WINCH_KNOCKS = [0.34, 0.68];// 桶磕井壁的深度：井口一黑就到底，深浅靠这两声
const WINCH_DUNK_DX = -0.42;      // 墩桶的站位：胳膊半米长，得往前挪一步才够得着绳（实拍量的：−0.52 时手还差 11 厘米）
const WINCH_BUCKET_TOP = 0.66;    // 桶提到顶时的高度（＝World 画桶那条线，别另抄）
export const WINCH_LAND_X = 0.62; // 拽到井沿要横着拉多远（World 画桶也读它）
// ── 井底那扇小窗 ──
